import React, { useState } from "react";
import { Link, useNavigate } from 'react-router-dom';

function PaymentMethod() {
    const [Email, setEmail] = useState('')
    const [Password, setPassword] = useState('')
    const navigate = useNavigate()

    async function AddPaymentMethod(event) {
        event.preventDefault()

        const userData = {
            Email,
            Password
        };

        if (!Email || !Password) {
            alert('Пожалуйста заполните все поля');
            return;
        } else {
            const response = await fetch(`${process.env.REACT_APP_USER_SERVICE_URL}/login`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(userData),
            });
            const data = await response.json()

            if (data.token) {
                localStorage.setItem('token', data.token)
                localStorage.setItem('role', data.roles)
                localStorage.setItem('renterId', data.renterId)
                fetchOrder();
                setClearTime();
                alert('Авторизация успешна')
                navigate('/Home')
            }
            else {
                alert('Please check your username and password')
            }
        }
    }

    return (
        <div className="Subscription">
            <h1>Детали оплаты</h1>
            <h3>Осталось совсем немного. Всего лишь некоторые платежные реквизиты, и вы сможете сделать свой первый заказ уже сегодня. (Первая доставка бесплатно!)</h3>
            <div className="line"></div>

        </div>
    )
}

export default PaymentMethod;
